// MarshalXML serializes ImplementationGuideManifestResource to FHIR-conformant XML.
func (b ImplementationGuideManifestResource) MarshalXML(e *xml.Encoder, start xml.StartElement) error {
	if start.Name.Local == "" {
		start.Name.Local = "ImplementationGuide.manifest.resource"
	}
	if b.Id != nil {
		start.Attr = append(start.Attr, xml.Attr{Name: xml.Name{Local: "id"}, Value: *b.Id})
	}
	if err := e.EncodeToken(start); err != nil {
		return err
	}

	for _, item := range b.Extension {
		if err := item.MarshalXML(e, xml.StartElement{Name: xml.Name{Local: "extension"}}); err != nil {
			return err
		}
	}
	for _, item := range b.ModifierExtension {
		if err := item.MarshalXML(e, xml.StartElement{Name: xml.Name{Local: "modifierExtension"}}); err != nil {
			return err
		}
	}
	if b.Reference != nil {
		if err := b.Reference.MarshalXML(e, xml.StartElement{Name: xml.Name{Local: "reference"}}); err != nil {
			return err
		}
	}
	if err := xmlEncodePrimitiveBool(e, "isExample", b.IsExample, b.IsExampleExt); err != nil {
		return err
	}
	if err := xmlEncodePrimitiveStringArray(e, "profile", b.Profile, b.ProfileExt); err != nil {
		return err
	}
	if err := xmlEncodePrimitiveString(e, "relativePath", b.RelativePath, b.RelativePathExt); err != nil {
		return err
	}

	return e.EncodeToken(start.End())
}

// UnmarshalXML deserializes ImplementationGuideManifestResource from FHIR-conformant XML.
func (r *ImplementationGuideManifestResource) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {
	for _, attr := range start.Attr {
		if attr.Name.Local == "id" {
			v := attr.Value
			r.Id = &v
		}
	}

	for {
		tok, err := d.Token()
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "extension":
				var v Extension
				if err := v.UnmarshalXML(d, t); err != nil {
					return err
				}
				r.Extension = append(r.Extension, v)
			case "modifierExtension":
				var v Extension
				if err := v.UnmarshalXML(d, t); err != nil {
					return err
				}
				r.ModifierExtension = append(r.ModifierExtension, v)
			case "reference":
				var v Reference
				if err := v.UnmarshalXML(d, t); err != nil {
					return err
				}
				r.Reference = &v
			case "isExample":
				v, ext, err := xmlDecodePrimitiveBool(d, t)
				if err != nil {
					return err
				}
				r.IsExample = v
				r.IsExampleExt = ext
			case "profile":
				v, ext, err := xmlDecodePrimitiveString(d, t)
				if err != nil {
					return err
				}
				// nil is meaningful here: it is a positional slot with no value.
				r.Profile = append(r.Profile, v)
				r.ProfileExt = appendExtSlot(r.ProfileExt, ext, len(r.Profile))
			case "relativePath":
				v, ext, err := xmlDecodePrimitiveString(d, t)
				if err != nil {
					return err
				}
				r.RelativePath = v
				r.RelativePathExt = ext
			default:
				if err := d.Skip(); err != nil {
					return err
				}
			}
		case xml.EndElement:
			r.ProfileExt = alignExtSlots(r.ProfileExt, len(r.Profile))
			return nil
		}
	}
}

